using System;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;using ProjectWait.M.Elevator;using Object=UnityEngine.Object;public static class VerifyPlayRI{public static async Task<string> Main(){EditorApplication.ExecuteMenuItem("Window/General/Game");var l=Object.FindFirstObjectByType<ElevatorLesson>();for(int i=0;i<50&&(l==null||l.Flow==null);i++){await Task.Delay(100);l=Object.FindFirstObjectByType<ElevatorLesson>();}l.DeveloperJump(2);await Task.Delay(1000);var controller=Object.FindFirstObjectByType<ElevatorDesktopControls>();var angle=Quaternion.LookRotation(l.friend.position+Vector3.up-l.playerCamera.transform.position).eulerAngles;controller.SetLookAngles(angle.y,Mathf.DeltaAngle(0,angle.x));await Task.Delay(250);await Awaitable.EndOfFrameAsync();var owner=Object.FindFirstObjectByType<ElevatorSceneRendering>();var pipeline=GraphicsSettings.currentRenderPipeline;var shaders=new[]{Shader.Find("ProjectWait/M/Outline Coverage"),Shader.Find("ProjectWait/M/Outline Distance")};bool success=pipeline==owner.scenePipeline&&ElevatorSilhouetteOutlineFeature.LastFrame>=Time.frameCount-2&&ElevatorSilhouetteOutlineFeature.LastTargetCount>2&&shaders.All(s=>s&&!ShaderUtil.ShaderHasError(s));ScreenCapture.CaptureScreenshot("Assets/M/CodexTemp/OutlineRendererTool_20261030~/InstalledRendererPlay.png");var report=Newtonsoft.Json.JsonConvert.SerializeObject(new{success,pipeline=AssetDatabase.GetAssetPath(pipeline),frame=Time.frameCount,lastFrame=ElevatorSilhouetteOutlineFeature.LastFrame,targets=ElevatorSilhouetteOutlineFeature.LastTargetCount,shaderErrors=shaders.Sum(s=>ShaderUtil.GetShaderMessages(s).Length)});File.WriteAllText("Assets/M/CodexTemp/OutlineRendererTool_20261030~/PlayVerification.json",report);return report;}}